package com.nivor.file;
import com.nivor.common.entity.AuditedEntity;import com.nivor.project.Project;import com.nivor.user.User;import jakarta.persistence.*;
@Entity @Table(name="file_assets",indexes=@Index(name="idx_file_user_created",columnList="user_id,created_at"))public class FileAsset extends AuditedEntity{@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="user_id",nullable=false)private User user;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="project_id")private Project project;@Column(nullable=false,length=240)private String originalName;@Column(nullable=false,length=80)private String storedName;@Column(nullable=false,length=120)private String mimeType;@Column(nullable=false)private long size;@Column(nullable=false,length=100)private String storageKey;@Column(length=60)private String category;protected FileAsset(){}public User getUser(){return user;}public void setUser(User v){user=v;}public Project getProject(){return project;}public void setProject(Project v){project=v;}public String getOriginalName(){return originalName;}public void setOriginalName(String v){originalName=v;}public String getStoredName(){return storedName;}public void setStoredName(String v){storedName=v;}public String getMimeType(){return mimeType;}public void setMimeType(String v){mimeType=v;}public long getSize(){return size;}public void setSize(long v){size=v;}public String getStorageKey(){return storageKey;}public void setStorageKey(String v){storageKey=v;}public String getCategory(){return category;}public void setCategory(String v){category=v;}}
